export function buildFormalParameters(): T.EmptyFormalParameters;
export function buildFormalParameters(
	value?: AdmitBound<T.FormalParametersElements, T.AdmittedNodes>
): ReturnType<typeof _buildFormalParameters>;
export function buildFormalParameters(
	options: { delimiter?: Delimiter.None | Delimiter.Trailing },
	...elements: NonEmptyArray<AdmitBound<T.RequiredParameter | T.OptionalParameter, T.AdmittedNodes>>
): ReturnType<typeof _buildFormalParameters>;
export function buildFormalParameters(
	...elements: NonEmptyArray<AdmitBound<T.RequiredParameter | T.OptionalParameter, T.AdmittedNodes>>
): ReturnType<typeof _buildFormalParameters>;
export function buildFormalParameters(...args: unknown[]) {
	if (args.length === 0 || (args.length === 1 && typeof args[0] !== 'object' && typeof args[0] !== 'number')) {
		return _buildFormalParameters(args[0] as T.FormalParametersElements);
	}
	const prebuilt =
		args.length === 1 &&
		typeof args[0] === 'object' &&
		args[0] !== null &&
		(args[0] as { $type?: unknown }).$type === (TSKindId.FormalParametersElements as const);
	return prebuilt
		? _buildFormalParameters(args[0] as T.FormalParametersElements)
		: _buildFormalParameters(
				(buildFormalParametersElements as (...a: unknown[]) => unknown)(...args) as T.FormalParametersElements
			);
}
function _buildFormalParameters(
	value?: AdmitBound<T.FormalParametersElements, T.AdmittedNodes>
): T.FormalParameters.Bound {
	const _formal_parameters_elements = rejectBareText(
		value,
		'FormalParameters.formalParametersElements',
		'a built FormalParametersElements'
	);
	return withMethods(
		withListView(
			withListSlots(
				withAccessors(
					{
						$type: TSKindId.FormalParameters as const,
						$source: 2 as const,
						$named: true as const,
						_formal_parameters_elements,
						$with: {
							formalParametersElements: (value?: T.FormalParametersElements) => buildFormalParameters(value)
						}
					},
					{
						formalParametersElements: () => _formal_parameters_elements
					}
				),
				[
					{
						slot: 'formalParametersElements',
						kind: TSKindId.FormalParametersElements as const,
						optional: true,
						make: buildFormalParametersElements
					}
				]
			),
			{
				list: { accessor: 'formalParametersElements', storage: '_formal_parameters_elements' },
				elements: 'formalParameters',
				count: '_formal_parameter',
				options: [{ key: 'delimiter', default: Delimiter.None }]
			}
		)
	) as unknown as T.FormalParameters.Bound;
}

